25	        long ownersInCity = OwnerCities.countInCity(ownerRepository, owner.getCity());
26	        owner.setCapacityWarning(
27	                ownersInCity >= WARNING_THRESHOLD && ownersInCity < OwnerCities.CITY_CAPACITY);
28	    }
